+
+        var raw = JSON.parse(h.files['input/PROJ-123/pr_discussions_raw.json']);
+        assert.ok(raw && Array.isArray(raw.threads) && raw.threads.length === 0,
+            'AC3: empty-after-filter ships the {"threads":[]} contract placeholder');
