    BOT_AUTHORS: BOT_AUTHORS,
    stripLeadingHeading: stripLeadingHeading,
    isMachineNoticeBody: isMachineNoticeBody,
    isMachineNotice: isMachineNotice,
    isBotAuthor: isBotAuthor
};

