        mocks || {}
    );
}

/** GitHub provider wired exactly as createScm does for a configured repo. */
function makeGithubScm(mocks) {
    return loadScm(mocks).createScm({
        scm: { provider: 'github' },
        repository: { owner: 'org', repo: 'repo' }
