        conversations.push(makeProviderConversation(900 + i, null, NOTICE_BODIES[i], 'ai-teammate'));
    }
    realThreadsFixture().forEach(function(t) {
        conversations.push(makeProviderConversation(t.id, t.path, t.body, t.author));
